    provisionalConclusion:'児島で繊維産業が続いた理由は、綿花やジーンズという特定の商品に依存し続けたからではない。織る、裁つ、縫う、仕上げるという工程と、それを支える人材・設備・分業を別の商品へ繰り返し載せ替えたことが、産地の連続性をつくった。',
    openQuestions:['児島と井原の生地・縫製・加工分業を一つの産業圏としてどこまで描くべきか','北前船肥料が児島綿作へ与えた量的寄与を史料で精密化できるか','企業系譜を追うと工程の継承がどこまで実証できるか'],
