      {id:4,title:'鞆の浦について／常夜燈',publisher:'福山市',url:'https://www.city.fukuyama.hiroshima.jp/soshiki/kanko/85750.html'},
      {id:5,title:'尾道市歴史的風致維持向上計画（住吉浜と住吉神社）',publisher:'尾道市',url:'https://www.city.onomichi.hiroshima.jp/uploaded/attachment/33514.pdf'},
      {id:6,title:'住吉神社',publisher:'尾道観光協会',url:'https://www.ononavi.jp/spots/detail.html?detail_id=336'},
      {id:7,title:'尾道市の北前船構成文化財・住吉神社',publisher:'北前船データベース',url:'https://kitamae-bune-db.com/db/area_cat/onomichi/'}
