          {text:'港には、荷を扱う仕事とともに、商取引や信用を支える仕事もあった。一方で、船をつくる仕事の歴史は、海に囲まれた島側の条件や事業者の選択を抜きには説明できない。両者の関係を考えるには、同じ風景に見えても資料を分けて読む必要がある。',refs:[]},
          {text:'坂道の寺から水道を見下ろすと、船のいる海と対岸の工場が視界に入る。何世紀も離れた仕事を、一つの眺めの中で読むことができる。だが、その間に一本の線を引くには、まだ調べるべきことがある。',refs:[]}
