    lead:'御手洗の港には、石段のような雁木が残っている。船から人や荷を揚げるための階段だ。その背後の狭い土地には、商家や船宿、茶屋が並んだ。風や潮が合わなければ帆船は次の港へ進めない。航海の途中で生まれる「待ち時間」が、ここでは町の仕事になった。やがて船の進み方が変わると、港の仕事も変わった。それでも雁木と町並みが残るのはなぜだろう。',
