          {text:"1974年に開設された南風泊市場には、のちに活魚施設や荷さばき施設が増設された。魚を集め、そのまま全国へ送り出すのではなく、生きた魚を受け入れ、状態を整えて買い手へ渡すための設備がある。",refs:[3]},
          {text:"「活かし込み」は、生きたトラフグを水槽などで管理する工程である。農林水産省が登録した「下関ふく」も、この工程を特性の一つに挙げている。ただし、何日置けば必ず品質が高まるという単純な話ではない。魚の状態を見極め、出荷に向けて管理すること自体が専門の仕事なのだ。",refs:[5]},
          {text:"港に着いた時刻と、客が欲しい時刻が一致するとは限らない。魚を一時的にとどめておく設備と技能は、その時間差を調整する役割も持つ。",refs:[3,5]}
