          {text:"下関で「みがき」と呼ばれるのは、専門の技術によって有毒部位などを取り除き、食用にできる状態へ処理する工程である。山口県では、ふぐの処理に資格と施設の条件が定められている。魚を集める市場だけでは、この商品は成り立たない。",refs:[5,6]},
          {text:"「下関ふく」の価値を生む場所を考えるなら、魚が水揚げされた岸壁だけでなく、処理を担う人と施設を見なければならない。そこには、流通と食品安全が一体になった仕事がある。",refs:[5,6]}
