          {text:"観光客が見ているのは、皿の上に届いた魚と市場のにぎわいである。南風泊で魚を受ける人々が向き合うのは、産地も状態も異なる魚を選別し、安全に処理して需要地へ送る仕事だ。下関のふく文化を一つの市場風景だけで説明することはできない。",refs:[3,4]}
