    provisionalConclusion:'南風泊市場には複数の漁場・養殖地からふぐが届く。GI「下関ふく」は、定められた区域と行程で活かし込み・みがき処理を経たトラフグに関する名称であり、漁獲地だけで決まるものではない。地域名は魚そのものの出身地とは異なる、生産・加工・品質管理の仕事にも結びつく。',
    openQuestions:['GI下関ふくに該当する取扱量が南風泊市場の入荷総量に占める割合を追えるか','活かし込み・みがき・販売・飲食の各段階に付加価値がどのように配分されるか','南風泊市場の新旧設備整備と取扱量の関係を長期時系列で検証できるか'],
