          {text:'ここで価値の意味が変わる。かつては商売をするための家や蔵だったものが、後には歴史景観や観光資源になる。交易→資本→建築→文化という長い変換が起きた。',refs:[]},
          {text:'商流そのものは見えなくなっても、その利益で作られた空間は残る。柳井では、消えた経済ネットワークが都市景観へ姿を変えて保存された。',refs:[]}
