          {text:'引田では、港を囲むように岬が海へ突き出している。湾内は外海より風浪を避けやすく、岬は港を守る天然の壁になる。つまり港の価値は、人が後から造っただけではなく、まず地形によって与えられていた。',refs:[]},
          {text:'だから引田の成り立ちは、城から始めるより港から始めた方が分かりやすい。船が止まる価値ある場所があったからこそ、その場所を見張り、押さえる必要が生まれた。',refs:[]}
