          {text:'ここで、戦国期の港町からハマチ養殖までを一本の直系産業として結ぶのは無理がある。時代も技術も別物である。だが、引田では海を交通路として使うだけでなく、漁業・養殖という生産の場としても使う歴史が重なっていく。',refs:[]},
          {text:'港町の価値は「船が来る場所」だけではない。海へ出やすく、魚を扱い、市場へ運べることもまた、沿岸産業の基盤になる。',refs:[]}
