          {text:'高松の港が悪くなったわけではない。ネットワークそのものが変わり、「本州から四国へ行くなら高松を通る」という必然性が消えたのである。交通拠点の価値は、設備の立派さだけでなく、ネットワーク上の位置で決まる。',refs:[]},
          {text:'それでも行政、金融、商業、サービスといった県都機能は残った。長く交通拠点であったことで蓄積した都市機能まで、一つの航路が消えたからといって同時に消えるわけではない。ここに、交通拠点が地域へ残す「都市能力」が見える。',refs:[6]}
