          {text:'ここでは、鯛を炊飯へ溶け込ませるのではなく、刺身の食感と鮮度をそのまま飯に重ねる。調理時間が短く、一人分ずつ食べやすい点も、炊き込み型とは対照的である。',refs:[]},
          {text:'「漁師料理」という伝承を手掛かりにすると、船上や漁の現場に近い食事形態との関係が見えてくる。ただし、現在の料理形態がいつどのように固定されたかは、さらに史料で追う必要がある。',refs:[3,4]}
