          {text:'ここから見えるのは、郷土料理が食材の直接的な反映ではないということだ。同じ鯛でも、漁、鮮度、調理設備、食事人数、祝い事や日常食といった生活条件によって、料理の形は分岐する。',refs:[]},
          {text:'自然環境は「鯛が得られる」という可能性を与える。しかし、その鯛をどう料理へ変えるかは、人間側の選択である。ガストロノミーは、その両者の接点を読む分野なのである。',refs:[]}
