    lead:'魚をさばくと、鱗は真っ先に取り除かれる。小さく、硬く、食べにくい。だから廃棄物に見える。ところが鱗を成分に分けてみると、そこにはコラーゲンと無機質がある。愛媛・宇和島では、養殖真鯛の鱗を原料にコラーゲン製品をつくる企業がある。副産物を「形」ではなく「成分」で見ると、価値の序列は一変する。',
