          {text:'ここでは大量の低価格資源へ変えるのではなく、少量でも価値の高い食品・化粧品原料へ転換している。これは典型的なアップサイクルである。',refs:[]},
          {text:'宇和海の養殖業が大きいからこそ、同じ種類の副産物をまとまった量で集められる。産業集積は主製品だけでなく、副産物利用の原料供給条件もつくる。',refs:[]}
