          {text:'サーキュラーエコノミーでは、最も高価な用途だけを目指すより、品質の高い部分は高付加価値素材へ、それ以外は飼料や肥料へ、と段階的に使うカスケード利用が重要になる。',refs:[]},
          {text:'ウロコの事例は、「ゴミを宝に変えた」という成功物語よりも、同じ副産物の中にも複数の品質と出口が必要だということを教える。',refs:[]}
