          {text:'真鯛を「魚」という一つの商品ではなく、身・脂・骨・皮・鱗という素材群として見ると、加工産業の設計も変わる。食用部分の歩留まりを上げるだけでなく、副産物ごとに最適な出口を設計できる。',refs:[]},
          {text:'宇和島の鯛の価値は、身の味だけにあるのではない。養殖・加工の集積が生み出す副産物まで含めると、一尾の魚が地域にもたらす価値はまだ増やせる。',refs:[]}
