    openQuestions:['宇和島圏で年間どれだけの真鯛鱗が発生し、どの割合が再利用されているか','コラーゲン抽出後に残る無機成分はどのように利用できるか','皮・骨・内臓を含めた真鯛一尾全体のマテリアルフローを描けるか'],
