          {text:'県の別資料によれば、小豆島の肥育農家がオリーブオイル搾油後の果実を飼料化することに成功し、2010年度から「小豆島オリーブ牛」が展開され、その後県内全域へ「オリーブ牛」として広がった。',refs:[2]},
          {text:'ここでは、オリーブ産業の副産物が畜産の投入物へ変わっている。廃棄物処理ではなく、異なる産業の原料置換である。',refs:[1,2]}
