      {id:2,title:'「オリーブ牛」が商標登録されました',publisher:'香川県',url:'https://www.pref.kagawa.lg.jp/chikusan/olive/shohyo/wi28i1150306194147.html'},
      {id:3,title:'小豆島オリーブ牛をブランディングしてみまい！',publisher:'香川大学',url:'https://www.cpp.ao.kagawa-u.ac.jp/archive/2022y/entry-62.html'}
