          {text:'つまり醤油粕は、現在では「捨てるしかないもの」ではない。しかし、高い再利用率だけを見ても、地域の中でどのような相手へ渡されているのかは分からない。',refs:[]},
          {text:'小豆島では、その副産物が島内の農業へ戻る、非常に具体的な循環を見ることができる。',refs:[]}
