    provisionalConclusion:'小豆島の醤油粕利用は、食品副産物を単に肥料化する事例ではない。高い塩分という扱いにくい性質を、塩に強い長命草の栽培条件へ変換している。循環経済の本質を「廃棄物の無害化」ではなく「素材と利用先の相性設計」として考えることができる。',
    openQuestions:['小豆島で年間に発生する醤油粕量と島内利用量を把握できるか','醤油粕・オリーブ堆肥の配合率と土壌塩分・収量・栄養価の関係を定量化できるか','島内の醤油・オリーブ・農業をつなぐマテリアルフローを描けるか'],
