          {text:'ここでは島の地理が加工技術の一部になっている。漁場が遠ければ、同じ魚でも「伊吹いりこ」の品質にはなりにくい。',refs:[]},
          {text:'しかし、鮮度がよければすべて同じ商品になるわけではない。魚体の脂肪量が、次の分岐をつくる。',refs:[]}
