          {text:'通常の鮮魚なら「脂が乗っている」は褒め言葉である。ところが、乾燥させて澄んだ出汁を取る商品では、同じ脂が欠点になる。',refs:[]},
          {text:'つまり魚の価値は、生物としての品質だけでなく、「何に加工するか」によって決まる。規格外とは、用途との不一致なのである。',refs:[]}
