          {text:'重要なのは、新しい用途のために魚を改良したのではなく、加工方法を変えたことである。乾燥工程を外せば、酸化しやすい脂は「雑味の原因」から「おいしさ」へ戻る。',refs:[3]},
          {text:'廃棄物を後から再利用するより、価値が落ちる工程そのものを避ける。これは循環経済における「発生抑制」に近い考え方である。',refs:[]}
