          {text:'そのとき、自然を以前の規格に戻そうとするだけでなく、加工方法や商品側を変えるという対応がある。伊吹島の取り組みは、海の変化に産業が適応する一例としても読める。',refs:[]},
          {text:'「良い魚／悪い魚」という区分は固定ではない。用途が変われば、同じ魚の価値も変わる。循環経済とは、物質だけでなく規格と市場を組み替えることでもある。',refs:[]}
