    openQuestions:['漁獲量のうち脂イワシが占める割合は長期的にどう変化しているか','新商品化によって従来の肥料利用・島内消費からどれだけ高付加価値用途へ移行したか','脂肪量・水温・餌環境の関係を長期データで検証できるか'],
