    heroPhotoId:'photo-ehime-citrus-orchard',
    lead:'みかんジュースを飲むと、果実の大部分が液体になったように思える。実際には、搾汁すると皮や袋、果肉など大量の固形物が残る。えひめ飲料では、みかんを搾る際に重量のおよそ半分が搾汁粕になり、2023年度には4,185トンが発生した。その約90％は飼料として利用された。一方、同じ柑橘残渣からセルロースナノファイバーという高機能素材をつくる技術も愛媛で生まれている。大量利用と高付加価値利用をどう組み合わせるか。ここに循環経済の「価値の階段」が見える。',
