          {text:'産地では「ジュースを何本つくったか」が表側の生産量になる。しかし物質収支で見れば、同時に数千トン規模の副産物をどう扱うかという工程が存在する。',refs:[]},
          {text:'加工産業が大きくなるほど、副産物処理は環境部門ではなく、生産システムそのものの問題になる。',refs:[]}
