          {text:'2023年度には搾汁粕の約90％を飼料として利用し、主に四国、中国・九州の一部の畜産農家へ供給している。',refs:[1]},
          {text:'同じ「飼料化」でも、乾燥か発酵かでエネルギー負荷は変わる。循環の評価には、再利用率だけでなく、再利用のために投入するエネルギーも含める必要がある。',refs:[]}
