          {text:'同社が紹介する2014年の県内調査では、柑橘搾汁残渣は年間約1.8万トン発生し、約1割が陳皮、約6割が堆肥・飼料として利用され、約3割が廃棄されていた。こうした未利用部分に、機能性素材としての価値を見いだした。',refs:[2]},
          {text:'ただし高機能素材は単価が高くても、市場規模が小さければ何千トンもの残渣を吸収できない。大量に使う飼料と、少量を高く使う素材は競合ではなく、役割が違う。',refs:[]}
