          {text:'みかんの皮には香り、色素、機能性成分、繊維がある。一つの副産物の中にも価値の異なる成分が重なっている。搾汁粕を一括して「餌」にするだけでは、取り出せる価値を捨てている可能性がある。',refs:[]},
          {text:'逆に、すべてを高度精製すれば加工エネルギーとコストが膨らむ。地域の最適解は、高付加価値化と大量処理の組み合わせにある。',refs:[]}
