          {text:'産地の競争力を「高い糖度の果実」だけで測るのではなく、規格外果実や加工残渣まで含めて、果実一個からどれだけ価値を引き出せるかで考えることもできる。',refs:[]},
          {text:'サーキュラーエコノミーは、廃棄物問題の後処理ではない。加工産業そのものを「一つの原料から複数の製品をつくる産業」へ変える視点なのである。',refs:[]}
