    provisionalConclusion:'愛媛の柑橘搾汁粕は、大量部分を発酵飼料として利用しつつ、一部をセルロースナノファイバーなど高付加価値素材へ展開できる。重要なのは一つの用途ですべてを処理することではなく、量と品質に応じて用途を段階的に組み合わせるカスケード利用である。',
