    provisionalConclusion:'愛媛の柑橘剪定枝には、粉砕して牛舎の敷料にし、使用後に堆肥として農地へ戻すルートと、バイオ炭にして炭素を土壌へ長期貯留するルートがある。前者は機能と養分を段階的に使う循環、後者は循環速度を遅らせる炭素固定である。循環経済では、資源を「回す」だけでなく「どの速度で回すか」まで設計する必要がある。',
    openQuestions:['愛媛県内で年間に発生する柑橘剪定枝量を推計できるか','敷料化・堆肥化・バイオ炭化のコストとCO2収支を比較できるか','急傾斜園地から剪定枝を搬出する労力が各ルートの採算性をどう左右するか'],
