          {text:'つまり現在の巨大な平地は自然に存在していたのではない。海を締め切り、排水し続けることで成立した人工的な土地である。',refs:[1]},
          {text:'この出発点を押さえると、後の太陽光発電所も「空き地にパネルを置いた」のではなく、何十年も維持されてきた人工地盤の次の利用形態として見えてくる。',refs:[]}
