          {text:'1971年、国の第4次塩業整理により塩田は廃止され、製塩はイオン交換膜法による工場製塩へ転換した。土地に依存していた製塩が、設備中心の製塩へ変わったことで、巨大な塩田だけが取り残された。',refs:[1]},
          {text:'ここで失われたのは「塩をつくる機能」であって、広さ・平坦さ・日照という土地条件ではなかった。その条件が数十年後、別の太陽利用技術に再評価される。',refs:[]}
