          {text:'問題は、この土地が海面より低く、排水ポンプを止めれば跡地や周辺低地に浸水のおそれがあることだった。瀬戸内市は約500世帯への被害を避けるため、2010年に跡地を取得している。',refs:[1]},
          {text:'土地利用が終わっても土地管理は終わらない。干拓地は、使われなくなった瞬間に「自然へ戻る」のではなく、堤防・排水という維持装置を必要とし続ける。',refs:[]}
