          {text:'清水建設によれば、発電規模は235MW、発電所敷地260ヘクタール、パネル設置面積約230ヘクタールである。',refs:[4]},
          {text:'土地貸付料は建設期間と売電期間などを合わせた契約上の累計で100.5億円とされ、事業者は排水ポンプ増設、堤防補強など約32億円規模の安全安心事業も担う。太陽光は発電だけでなく、土地を維持する財源装置にもなった。',refs:[2]}
