          {text:'塩田では太陽熱と風で水分を飛ばし、海水から塩を得た。現在は太陽光を半導体で電気へ変える。土地の基本条件は同じでも、社会が求める生産物と技術が変わった。',refs:[]},
          {text:'錦海の景観は、再生可能エネルギーの風景であると同時に、瀬戸内で土地が繰り返しつくり替えられてきた歴史の最新版なのである。',refs:[]}
