    heroPhotoId:'photo-solar-sharing-comparative',
    lead:'日射の多い瀬戸内で太陽光発電を増やそうとすると、次に問題になるのは「どこへ置くか」である。屋根だけでは足りず、平坦で日当たりのよい土地は発電にも農業にも向く。一方、日本では荒廃農地が増えている。農地を発電へ転用するのか、営農を続けながら上部で発電するのか。エネルギーと食料が、同じ平方メートルを取り合う時代になった。',
