          {text:'瀬戸内は日照条件に恵まれる一方、沿岸平地は都市・工業・農地としてすでに使われている。新しい発電所は既存の土地利用と競合しやすい。',refs:[]},
          {text:'再エネを増やすという全国目標と、地域の一筆一筆の土地利用は、同じ問題の別の尺度である。',refs:[]}
