          {text:'一見すれば、こうした土地へ太陽光を置けば農業と競合しないように思える。しかし、再生可能な農地を恒久的に転用すれば、将来の食料生産基盤を失う可能性もある。',refs:[]},
          {text:'「今使われていない」と「将来も農地として不要」は同じではない。土地利用には時間軸が必要である。',refs:[]}
