          {text:'これは土地を農業か発電かの二択にしない発想である。同じ土地の垂直方向を分け、光という資源を農作物と発電設備で配分する。',refs:[]},
          {text:'一方、農水省は下部農地で十分な営農が行われない事例も約2割あったと報告しており、2024年から許可基準を法令上明確化した。両立には実態のある農業が必要である。',refs:[4]}
