          {text:'香川県は2026年7月施行のガイドライン改正で、太陽光発電施設について地域説明、環境・災害影響、廃止時の処分方法や撤去後写真まで求める方向を強めた。',refs:[5]},
          {text:'土地を使う発電は、発電設備だけの問題ではない。20年、30年後にその土地を何へ戻せるかまで含めて、土地利用として設計される必要がある。',refs:[]}
