    provisionalConclusion:'日射の多い地域では、太陽光発電の拡大は土地利用競争として現れる。荒廃農地は候補になり得るが、「現在使われていない」ことと「農地として不要」は同義ではない。営農型太陽光は農業と発電を重ねる選択肢だが、実際の営農継続が前提になる。再エネ政策は、発電量ではなく土地の将来用途まで含めて評価する段階に入っている。',
    openQuestions:['瀬戸内沿岸各県で太陽光目的に転用された農地面積を時系列で比較できるか','耕作放棄地・再生可能農地・再生困難農地で太陽光立地の適否を分ける基準を作れるか','営農型太陽光の作物収量・発電量・所得を地域別に比較できるか'],
